"use strict";exports.id=5056,exports.ids=[5056],exports.modules={15056:(a,b,c)=>{c.d(b,{Y2:()=>d,Vf:()=>f,Ck:()=>e,PB:()=>i,C8:()=>g,gM:()=>h,_i:()=>k,Tl:()=>j,i$:()=>l});let d="/guides",e=[{slug:"trending",title:"Why Is It Trending in India?",shortTitle:"Trending",template:"[Trending Topic] — Why is it trending?",description:"Clear explainers on why topics spike on Google Trends, social media, and news in India — context, timeline, and what to watch next.",keywords:["why is it trending india","google trends india","trending topics explained"],badge:"Trends",relatedHub:{href:"/blogs?sort=trending",label:"Trending articles"}},{slug:"cricket",title:"Cricket Match Guides — Live Updates & Key Moments",shortTitle:"Cricket",template:"[Cricket Match] — Live Updates & Key Moments",description:"How to follow India cricket match days: key moments, scorecard reading, and where to get live updates on ContentVerse India Sports.",keywords:["cricket live updates india","match key moments","ipl live guide"],badge:"Sports",relatedHub:{href:"/sports",label:"Live Sports hub"}},{slug:"schemes",title:"Government Schemes — Eligibility & How to Apply",shortTitle:"Govt Schemes",template:"[Government Scheme] — Eligibility & How to Apply",description:"India government scheme explainers: who is eligible, documents needed, and how to apply on official portals — with clear disclaimers.",keywords:["govt schemes india","pm scheme eligibility","how to apply government scheme"],badge:"Yojana"},{slug:"jobs",title:"Job Notifications — Eligibility, Salary & Last Date",shortTitle:"Job Alerts",template:"[Job Notification] — Eligibility, Salary & Last Date",description:"How to read sarkari and private job notifications: eligibility, pay scale, last date, and official apply links.",keywords:["sarkari job notification","job eligibility salary last date","government job guide india"],badge:"Careers",relatedHub:{href:"/jobs/govt",label:"Govt jobs hub"}},{slug:"ai-tools",title:"AI Tools — How to Use Them in India",shortTitle:"AI Tools",template:"[AI Tool] — How to Use It",description:"Practical how-tos for popular AI tools — setup, prompts, privacy tips, and use-cases for students and creators in India.",keywords:["ai tools how to use","chatgpt guide india","free ai tools tutorial"],badge:"AI",relatedHub:{href:"/tools",label:"India Tools"}},{slug:"movies",title:"Movies & Web Series — Release, Cast & Where to Watch",shortTitle:"Movies / OTT",template:"[Movie/Web Series] — Release Date, Cast & Where to Watch",description:"India OTT and cinema guides: release dates, cast, and where to watch legally on Netflix, Prime, JioCinema, and more.",keywords:["where to watch ott india","movie release date cast","web series india guide"],badge:"OTT",relatedHub:{href:"/cineverse",label:"CineVerse"}},{slug:"money",title:"Money Guides — EMI, SIP, IFSC, Tax & GST",shortTitle:"Money",template:"[Money Topic] — How It Works in India",description:"Practical India money explainers: EMI and SIP maths, IFSC transfers, salary tax regimes, and GST on invoices — with free calculators and clear disclaimers.",keywords:["emi calculator guide india","sip beginners india","ifsc code guide","salary tax regime india","gst invoice calculator"],badge:"Money",relatedHub:{href:"/tools",label:"India Tools"}}],f=[{slug:"fastag-india-eligibility-recharge-faq",section:"schemes",title:"FASTag in India — Eligibility, Buy, Recharge & Common FAQ (2026)",shortTitle:"FASTag guide",description:"Complete FASTag guide for India: who needs it, how to buy and activate, recharge via UPI, blacklist fixes, double-toll disputes, and NHAI/IHMCL safety tips — updated Aug 2026.",keywords:["fastag india","fastag recharge","fastag eligibility","how to buy fastag","fastag blacklist","nhai fastag","fastag not working","fastag double deduction","ihmcl fastag","fastag for two wheeler"],readingMinutes:14,updatedLabel:"Aug 2026",relatedHref:"/tools/fuel-price",relatedLabel:"Check fuel prices",clusterId:"fastag",faqs:[{q:"Is FASTag mandatory in India?",a:"On most national highway toll plazas, FASTag is the expected payment method. Cash lanes may charge a higher fee or be limited. Rules can change — confirm on NHAI / IHMCL channels for your route."},{q:"How do I recharge FASTag?",a:"Use your issuer bank’s app, net banking, or UPI linked to the FASTag wallet. After payment, wait a few minutes and verify the balance in the issuer app before a long trip."},{q:"Why is my FASTag blacklisted?",a:"Common reasons: low or zero balance, KYC pending, mismatched vehicle number, or issuer-side holds. Top up, complete KYC in the issuer app, then wait for the blacklist to clear (can take hours)."},{q:"Can one FASTag be used on two vehicles?",a:"No. One FASTag is typically mapped to one registration number. Affixing the same tag on another vehicle can cause failed reads or account issues."},{q:"What if the plaza deducted twice?",a:"Note plaza name, time, lane, and SMS. Raise a dispute with your FASTag issuer first with screenshots. Keep the toll receipt if any cash fallback was used."}],blocks:[{heading:"What FASTag is (and why highways need it)",paragraphs:["FASTag is an RFID sticker linked to a prepaid wallet or bank account. Toll plazas on many national highways scan the tag so vehicles can pass without cash queues. The system is run through NHAI / IHMCL frameworks with bank and payment partners — issuer rules and fees can differ.","Cars, commercial vehicles, and many two-wheelers on notified stretches are expected to use FASTag. Driving without a working tag can mean higher cash toll or penalties depending on plaza policy. Treat this page as an educational explainer; always confirm live rules on official portals before you buy or travel."]},{heading:"Who needs FASTag (eligibility in plain English)",paragraphs:["If you use national highways regularly — weekend trips, interstate office travel, logistics, taxis, or intercity buses — FASTag usually saves time and avoids cash-lane delays. Occasional city-only drivers may still want one for rare highway journeys so they are not stuck at a plaza without a working tag.","You generally need a valid vehicle registration (RC), a mobile number for OTP/alerts, and a bank account or wallet supported by an authorised FASTag issuer. Commercial fleets often manage multiple tags under a business account — check your issuer’s fleet product separately."],bullets:["Keep RC details ready when activating (registration number must match)","Affix the tag on the windscreen exactly as the issuer instructs — wrong placement fails reads","One FASTag maps to one vehicle registration in normal retail use","Two-wheeler FASTag availability depends on issuer and plaza network — confirm before you buy"]},{heading:"How to buy and activate FASTag",paragraphs:["You can usually buy FASTag from participating banks, authorised Point of Sale (POS) locations, or bank apps/websites that list FASTag products. Prefer well-known bank issuers over unknown roadside sellers who ask for OTP or remote access to your phone.","Activation links the tag ID to your vehicle number and a wallet or account. Complete KYC when asked (PAN/Aadhaar as required by the issuer). After activation, do a small test recharge and confirm the vehicle number shown in the app matches your RC before your first long highway trip."],bullets:["Buy only from banks / authorised POS listed by NHAI–IHMCL partners","Photograph the tag ID and keep the welcome SMS","Never share banking OTP to “activate FASTag” over WhatsApp"]},{heading:"How to recharge FASTag (UPI, app, net banking)",paragraphs:["Recharge via the issuer’s app, UPI, or net banking. Set a low-balance alert so you are not stuck with a declined plaza read. After recharge, wait a few minutes and confirm balance in the issuer app — some wallets take a short settlement delay.","Before a long trip (especially festival weekends), top up with a buffer above your expected tolls. Combine this with a fuel budget using ContentVerse India’s fuel price tool so cashflow surprises stay low."],bullets:["Enable SMS / push alerts for every plaza debit","Keep a second payment method ready if your tag fails at a plaza","Avoid third-party “instant recharge agents” that ask for OTP"]},{heading:"FASTag not working, blacklist, or double deduction",paragraphs:["If a plaza does not open: slow down safely, note plaza name, time, and lane, and check SMS. Common fixes — low balance top-up, wait for blacklist clear after KYC, re-affix tag if the windscreen film blocks RFID, or ask staff for the FASTag lane policy at that plaza.","If charged twice or charged while cash was also taken, raise a dispute with your issuer with screenshots and timestamps. Official blacklist / KYC status lives with your bank issuer and NHAI–IHMCL support channels — ContentVerse India does not process disputes."],bullets:["Screenshot failed transactions before leaving the plaza area if safe","Dispute first with the issuer app / helpline, not random social accounts","Pair trip planning with fuel estimates on our Fuel Price tool"]},{heading:"Documents & checklist before a highway trip",paragraphs:["A five-minute checklist prevents most FASTag failures: confirm balance, confirm vehicle number in the app, confirm tag is affixed correctly, and save issuer helpline numbers offline. If you changed the windscreen recently, re-validate the tag — RFID placement is easy to get wrong after glass work."],bullets:["Balance ≥ expected tolls + buffer","RC number matches app","Phone has network for OTP if issuer asks mid-trip","Alternate cash/UPI plan if plaza has issues"]}]},{slug:"emi-calculator-india-guide",section:"money",title:"EMI Calculator India — How Loan EMIs Work (Home, Car & Personal)",shortTitle:"EMI guide",description:"Understand EMI in India: formula in plain English, tenure vs interest trade-offs, floating-rate stress tests, and how to use our free EMI calculator before you sign.",keywords:["emi calculator india","home loan emi","personal loan emi","how emi is calculated","loan tenure vs interest","floating rate emi"],readingMinutes:12,updatedLabel:"Aug 2026",relatedHref:"/tools/emi-calculator",relatedLabel:"Open EMI calculator",clusterId:"emi-loans",faqs:[{q:"How is EMI calculated?",a:"EMI depends on principal, annual interest rate, and tenure in months. Higher tenure lowers monthly EMI but usually increases total interest paid. Always compare total interest, not only the monthly number."},{q:"Should I choose a longer tenure to reduce EMI?",a:"Only if the lower EMI fits your budget after stress-testing a rate hike. Longer tenure often means more total interest. Run 36 vs 48 vs 60 month scenarios in the calculator before you sign."},{q:"Is this calculator a loan offer?",a:"No. ContentVerse India’s EMI tool is an educational estimate. Bank processing fees, insurance, and floating-rate resets may not be inside a simple EMI formula — verify with the lender’s amortisation schedule."}],blocks:[{heading:"What EMI means for Indian borrowers",paragraphs:["EMI (Equated Monthly Instalment) is the fixed amount you pay each month toward a loan — part interest, part principal. Home loans, car loans, personal loans, and many consumer durables use EMI structures. Understanding the trade-off between monthly comfort and total interest is the real skill, not just finding the lowest advertised EMI.","Use our free EMI calculator to compare scenarios side by side, then verify numbers with the bank before signing. This guide is educational only — not a loan offer or credit advice."]},{heading:"EMI formula in plain English",paragraphs:["EMI rises when principal or interest rate rises, and falls when tenure lengthens. A longer tenure spreads principal over more months, so the monthly hit looks smaller — but interest accumulates for longer. Always ask for total interest payable and the amortisation schedule, not only the EMI line on a sales flyer."],bullets:["Shorter tenure = higher EMI, usually lower total interest","Floating rates can change EMI or tenure mid-loan","Processing fees and insurance may sit outside the EMI"]},{heading:"Practical planning tips before you borrow",paragraphs:["Keep total EMIs (existing + new) under a comfortable share of take-home salary. Stress-test a 1–2% rate hike if the loan is floating. Prepayment can cut interest — check prepayment charges and whether the bank reduces tenure or EMI after you prepay.","Compare bank offers with the same principal and tenure in our calculator, then confirm with Form 16 / salary slips the lender will underwrite against."]},{heading:"Worked example you can recreate",paragraphs:["Take ₹10 lakh at 12% p.a. for 48 months and note EMI and total interest. Then switch to 36 months: EMI rises, total interest usually falls. That comparison is more useful than any single “lowest EMI” screenshot from a marketplace ad."]}]},{slug:"sip-calculator-india-beginners-guide",section:"money",title:"SIP Calculator India — Beginner Guide to Systematic Investing",shortTitle:"SIP guide",description:"SIP explained for India: how monthly mutual fund investments work, how to read calculator projections, risk disclaimers, and beginner habits that stick.",keywords:["sip calculator india","sip for beginners","systematic investment plan","mutual fund sip","sip returns explained"],readingMinutes:11,updatedLabel:"Aug 2026",relatedHref:"/tools/sip-calculator",relatedLabel:"Open SIP calculator",clusterId:"sip-investing",faqs:[{q:"Does a SIP guarantee returns?",a:"No. SIP calculators assume a constant return for illustration. Equity and hybrid funds can be volatile year to year. Mutual fund investments are subject to market risks."},{q:"How much should I start a SIP with?",a:"Start with an amount you can continue for years without breaking household cashflow. Automate via bank mandate and increase when salary rises."},{q:"SIP vs FD — which is better?",a:"They solve different problems. FDs prioritise predictable rupee outcomes (issuer risk aside); SIPs in market-linked funds prioritise long-horizon growth with volatility. Many households use both — this is not personalised advice."}],blocks:[{heading:"What a SIP is (without jargon)",paragraphs:["A Systematic Investment Plan (SIP) invests a fixed amount into a mutual fund at regular intervals — usually monthly. The habit matters as much as the product: automation reduces the urge to time the market on every headline.","Our SIP calculator projects how monthly investments might grow under an assumed annual return. It is for planning conversations — not a guarantee and not SEBI-registered advice."]},{heading:"How to use the SIP calculator well",paragraphs:["Enter monthly amount, expected annual return %, and tenure in years. Review maturity value and estimated gains. Try conservative (8–10%), moderate (11–12%), and optimistic scenarios separately instead of one aggressive number.","Long horizons usually matter more than chasing last year’s top fund. Revisit asset allocation annually — not every market dip."]},{heading:"Beginner habits that actually stick",paragraphs:["Automate the SIP on salary day. Keep an emergency buffer in safer instruments so you do not pause SIPs for every expense spike. Read the scheme document. If you need personalised advice, consult a SEBI-registered adviser."],bullets:["Start small, stay consistent","Increase SIP with salary hikes","Do not confuse past returns with future results"]}]},{slug:"ifsc-code-finder-india-guide",section:"money",title:"IFSC Code Finder India — NEFT, RTGS & IMPS Without Mistakes",shortTitle:"IFSC guide",description:"Find and verify IFSC codes in India: 11-character format, when you need IFSC, how to avoid wrong transfers, and how to use our free IFSC finder safely.",keywords:["ifsc code finder","ifsc code india","neft ifsc","wrong ifsc transfer","bank branch ifsc"],readingMinutes:10,updatedLabel:"Aug 2026",relatedHref:"/tools/ifsc-finder",relatedLabel:"Open IFSC finder",clusterId:"banking-ifsc",faqs:[{q:"What does an IFSC look like?",a:"IFSC is 11 characters: 4 letters for the bank, a 0, then 6 characters for the branch (example pattern: SBIN0001234). Never invent a code — verify against passbook, cheque, or the bank’s official locator."},{q:"I sent money with the wrong IFSC — what now?",a:"Contact your bank immediately with UTR/reference number. Recovery depends on whether the credit succeeded and bank processes. Prevention (double-check before send) is far easier than reversal."},{q:"Is ContentVerse a bank?",a:"No. Our IFSC finder is a convenience utility. For disputes or official confirmation, use your bank or the bank’s official branch locator."}],blocks:[{heading:"Why IFSC matters",paragraphs:["IFSC (Indian Financial System Code) identifies every bank branch for NEFT, RTGS, and IMPS. Wrong IFSC can delay or bounce a transfer — or, in worst cases, credit the wrong branch path and create a recovery headache.","Salary accounts, vendor payments, loan EMIs, mutual fund mandates, and tax refunds all rely on correct IFSC. Freelancers should keep their primary branch IFSC saved in a trusted notes app."]},{heading:"How to find IFSC safely",paragraphs:["Start with bank name, then narrow by state and city, or search by branch. Cross-check against passbook, cheque book, or net banking. Prefer official bank SMS and statements for high-value first-time payees."],bullets:["Match beneficiary name + account number + IFSC together","Send a ₹1 test transfer to new vendors when practical","Avoid random websites that ask for OTP to “verify IFSC”"]},{heading:"NEFT vs IMPS vs RTGS (quick context)",paragraphs:["IMPS is typically for faster smaller transfers; NEFT/RTGS cover broader bank settlement use-cases and amount bands. Exact limits and timings change — confirm in your banking app before a time-critical payment."]}]},{slug:"salary-tax-calculator-india-guide",section:"money",title:"Salary Tax Calculator India — New vs Old Regime Explained",shortTitle:"Salary tax guide",description:"Estimate take-home tax in India: new vs old regime basics, what calculators can and cannot do, and how to verify on the Income Tax portal before filing.",keywords:["salary tax calculator india","new tax regime vs old","income tax slabs india","take home salary calculator","form 16 tax estimate"],readingMinutes:11,updatedLabel:"Aug 2026",relatedHref:"/tools/salary-tax-calculator",relatedLabel:"Open salary tax calculator",clusterId:"salary-tax",faqs:[{q:"Which is better — new or old regime?",a:"It depends on your deductions. The new regime uses revised slabs with fewer deductions; the old regime can win if you have large eligible deductions. Run both numbers, then confirm with Form 16 / a CA."},{q:"Is this the Income Tax Department portal?",a:"No. ContentVerse India’s calculator is an independent educational estimate. File and verify on the official Income Tax portal."}],blocks:[{heading:"Why salary tax estimates matter",paragraphs:["Choosing a tax regime without numbers is guessing. A calculator helps you compare take-home under simplified assumptions — standard deduction, slabs, and common inputs — before you lock a choice at filing time.","Rules, rebates, and surcharge thresholds change. Treat every output as a planning aid, then verify on the official e-filing utilities or with a qualified CA."]},{heading:"New vs old regime — quick context",paragraphs:["The new default regime uses revised slabs with fewer deductions. The old regime can still win with HRA, 80C, and other eligible claims. Enter the same CTC twice in our tool: once with new-regime defaults, once with old-regime deductions you actually claim."]},{heading:"What to verify before you file",paragraphs:["Match Form 16, employer TDS, and investment proofs. Section 87A rebates and surcharge rules can change year to year. Do not rely on a blog calculator alone for final liability."],bullets:["Keep Form 16 and AIS/TIS handy","Confirm regime choice deadlines with official guidance","Use the Income Tax portal for filing"]}]},{slug:"gst-calculator-india-freelancers-guide",section:"money",title:"GST Calculator India — Invoice GST for Freelancers & Small Business",shortTitle:"GST guide",description:"Split GST on invoices in India: exclusive vs inclusive GST, common rates (5/12/18/28), freelancer basics, and how to use our free GST calculator.",keywords:["gst calculator india","gst inclusive exclusive","freelancer gst","invoice gst 18%","gst rates india"],readingMinutes:10,updatedLabel:"Aug 2026",relatedHref:"/tools/gst-calculator",relatedLabel:"Open GST calculator",clusterId:"gst-business",faqs:[{q:"What is exclusive vs inclusive GST?",a:"Exclusive: tax is added on top of the base. Inclusive: the total already contains GST and you reverse-calculate the base. Know which mode your invoice uses."},{q:"Does this tool file GST returns?",a:"No. Use the official GST portal for registration, GSTR filing, and official computations. Our calculator is for quotes and invoice checks only."}],blocks:[{heading:"GST on everyday invoices",paragraphs:["Freelancers and small businesses constantly split GST at common rates (5%, 12%, 18%, 28%). Mistakes show up as awkward client conversations and messy books. A calculator helps you quote cleanly — registration and filing still happen only on the GST portal."]},{heading:"Exclusive vs inclusive — worked intuition",paragraphs:["Exclusive example: base ₹10,000 at 18% adds ₹1,800 → total ₹11,800. Inclusive mode starts from the total and recovers base + tax. Always state which mode you used on the quote."]},{heading:"Freelancer checklist (educational)",paragraphs:["Know whether you must register based on turnover thresholds (confirm current law officially). Keep GSTIN on invoices when registered. Separate tax collected from money you can spend. This is not tax advice — thresholds and composition scheme rules change."]}]},{slug:"why-topics-trend-in-india",section:"trending",title:"Why Topics Trend in India — Google Trends & News Spikes Explained",shortTitle:"Why topics trend",description:"Understand why a person, meme, or news event trends in India: search demand, social virality, and news cycles — and how to verify claims.",keywords:["why is it trending","google trends india explained"],readingMinutes:5,updatedLabel:"Jul 2026",relatedHref:"/blogs?sort=trending",relatedLabel:"See trending articles",blocks:[{heading:"What “trending” actually means",paragraphs:["In India, a topic can trend on Google Search, YouTube, X/Twitter, Instagram Reels, or WhatsApp forwards — often at the same time. Google Trends shows relative search interest, not absolute visitor counts. A spike usually means many people searched the same phrase in a short window.","News channels and social creators amplify the same keywords, which pushes more searches. That feedback loop is why “Why is X trending?” becomes a common query within hours."]},{heading:"A simple checklist before you share",paragraphs:["Trending does not mean verified. Use this quick filter before forwarding or writing about a spike:"],bullets:["Check at least two reputable Indian news outlets for the same claim","Look at Google Trends India for the keyword vs related breakout queries","Prefer primary sources (official handles, court filings, company statements)","Ignore screenshots without a date, URL, or named reporter"]},{heading:"How ContentVerse India covers trends",paragraphs:["Our Trending guides focus on context: what happened, why searches rose, and what is still unconfirmed. For evergreen reading, open Trending articles on the blogs hub. For live sports or market spikes, jump to Sports or Finance instead of rumour threads."]}]},{slug:"how-to-read-google-trends-india",section:"trending",title:"How to Read Google Trends India (Breakout Queries & Regions)",shortTitle:"Google Trends India",description:"Step-by-step guide to Google Trends for India: interest over time, breakout queries, related topics, and state-level interest.",keywords:["google trends india tutorial","breakout queries india"],readingMinutes:5,updatedLabel:"Jul 2026",blocks:[{heading:"Set the geography to India",paragraphs:["Open trends.google.com, search your keyword, and set the region to India. Compare the last 24 hours (fast news) with past 7 days or 90 days (lasting interest). A one-day spike that disappears is usually a news burst; a week-long rise may be a product launch or exam cycle."]},{heading:"Use related queries",paragraphs:["The “Related queries” panel is often more useful than the main chart. Breakout queries (marked Rising / Breakout) show what people type next — for example a celebrity name plus “wife”, “net worth”, or “died”. Those phrases reveal intent and help you write a useful explainer instead of a vague headline."],bullets:["Rising = growing vs previous period","Breakout = huge relative increase (treat carefully — can be rumour-driven)","Compare Hindi and English spellings separately when relevant"]}]},{slug:"live-cricket-match-day-guide",section:"cricket",title:"Cricket Match Day Guide — Live Updates & Key Moments",shortTitle:"Match day guide",description:"Follow an India cricket match day the smart way: toss, key moments, scorecard basics, and where to get live updates without spam.",keywords:["cricket live updates","match key moments india"],readingMinutes:5,updatedLabel:"Jul 2026",relatedHref:"/sports",relatedLabel:"Open Sports hub",blocks:[{heading:"What to track during a live match",paragraphs:["A useful match guide is not only the final score. Note toss and decision, powerplay or new-ball phases, partnerships that change the game, reviews, and bowling spells that swing momentum. Those “key moments” are what fans search for hours after the match."],bullets:["Toss + pitch note (bat/bowl first)","Breakthrough wickets and partnerships","Death overs / slog overs impact","Player of the match context (not only the award name)"]},{heading:"Where to follow on ContentVerse India",paragraphs:["Use the Sports hub for live and recent fixtures, then return here for explainers on how we structure match coverage. Avoid unofficial streaming links — prefer official broadcasters and licensed apps in India."]}]},{slug:"how-to-read-a-cricket-scorecard",section:"cricket",title:"How to Read a Cricket Scorecard (India Fans’ Quick Guide)",shortTitle:"Read a scorecard",description:"Learn batting, bowling, extras, and run-rate lines on an Indian cricket scorecard so live updates make sense.",keywords:["how to read cricket scorecard","cricket extras explained"],readingMinutes:4,updatedLabel:"Jul 2026",relatedHref:"/sports",relatedLabel:"Live scores",blocks:[{heading:"Batting line",paragraphs:["Runs (R), balls (B), fours, sixes, and strike rate tell how a batter scored. “Not out” means they were still batting when the innings ended. Fall of wickets shows when momentum shifted."]},{heading:"Bowling & extras",paragraphs:["Overs, maidens, runs conceded, and wickets form the bowling summary. Extras (wides, no-balls, byes, leg-byes) are runs not credited to a batter. In T20, economy rate often matters as much as wickets."]}]},{slug:"pm-kisan-eligibility-how-to-apply",section:"schemes",title:"PM-KISAN — Eligibility & How to Apply (India Guide)",shortTitle:"PM-KISAN guide",description:"Overview of PM-KISAN farmer support: who is typically eligible, documents commonly needed, and how to apply or check status on the official portal.",keywords:["pm kisan eligibility","pm kisan how to apply","pm kisan yojana"],readingMinutes:6,updatedLabel:"Jul 2026",blocks:[{heading:"What the scheme is",paragraphs:["PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) is a Central government income-support scheme for eligible landholding farmer families in India. Benefits and rules can change — always confirm on the official PM-KISAN portal before applying."]},{heading:"Eligibility (high-level)",paragraphs:["In general, the scheme targets farmer families who own cultivable land as per state land records. Many institutional landholders and higher-income categories are excluded. States upload beneficiary data; farmers should verify their name, Aadhaar seeding, and bank account details."],bullets:["Confirm land record details with your state revenue / agriculture office if needed","Keep Aadhaar and bank account linked and active","Use only pmkisan.gov.in (or the official app/link published by the Ministry)"]},{heading:"How to apply / check status",paragraphs:["New registrations and e-KYC are handled through the official website or authorised Common Service Centres (CSC), depending on your state’s process. After submission, track payment status and e-KYC flags on the same portal. ContentVerse India does not collect scheme applications — we only explain the process."]}]},{slug:"how-to-verify-govt-scheme-before-you-apply",section:"schemes",title:"How to Verify a Government Scheme Before You Apply",shortTitle:"Verify schemes safely",description:"Avoid fraud: check official .gov.in domains, helplines, and documents before sharing Aadhaar or paying agents for government schemes.",keywords:["government scheme fraud india","verify pm scheme official website"],readingMinutes:5,updatedLabel:"Jul 2026",blocks:[{heading:"Official sources only",paragraphs:["Real Central and State schemes publish details on .gov.in / .nic.in sites or the India.gov.in directory. Be careful with WhatsApp PDFs that ask for fees to “approve” a scheme. Most genuine applications do not need you to pay a private agent."],bullets:["Match the scheme name on an official ministry or MyGov page","Never share OTP / Aadhaar QR casually over chat","Prefer CSC / state portals for assisted applications"]},{heading:"Documents checklist pattern",paragraphs:["Most schemes ask for identity (Aadhaar), bank details, and a category proof (income, caste, farmer land, disability, etc.). Photocopy and keep soft copies ready, but upload only on official forms."]}]},{slug:"how-to-read-sarkari-job-notification",section:"jobs",title:"How to Read a Sarkari Job Notification (Eligibility, Salary, Last Date)",shortTitle:"Read job notifications",description:"Decode government job ads: post name, vacancy, age limit, education, pay level, fee, and last date — before you apply.",keywords:["how to read sarkari naukri notification","job eligibility salary last date"],readingMinutes:6,updatedLabel:"Jul 2026",relatedHref:"/jobs/govt",relatedLabel:"Browse govt jobs",blocks:[{heading:"Start with post + vacancy + last date",paragraphs:["Open the official PDF from the commission or department website. Note the exact post name, number of vacancies, opening date, and closing date/time (IST). Set a reminder 48 hours before the last date — portals often slow down near deadlines."]},{heading:"Eligibility & salary lines",paragraphs:["Age limits usually include category relaxations (OBC/SC/ST/PwBD/Ex-servicemen) — read the relaxation table carefully. Education must match the notification wording (for example “degree from a recognised university”). Pay is often shown as Pay Level / matrix plus allowances; take-home differs by city and deductions."],bullets:["Confirm age as on the date mentioned in the notice","Check whether experience is essential or desirable","Note application fee and exemption categories"]},{heading:"Apply on the official link only",paragraphs:["Use the URL printed in the notification. ContentVerse India Jobs lists government updates and deep-links to official sources where available — always complete payment and final submit on the commission’s site."]}]},{slug:"ssc-style-exam-notification-checklist",section:"jobs",title:"SSC-Style Exam Notification Checklist for First-Time Applicants",shortTitle:"Exam notification checklist",description:"A practical checklist for SSC and similar central exam notices: registration, documents, photo specs, and correction window.",keywords:["ssc notification checklist","sarkari exam apply guide"],readingMinutes:5,updatedLabel:"Jul 2026",relatedHref:"/jobs/govt",relatedLabel:"Latest govt updates",blocks:[{heading:"Before you register",paragraphs:["Keep a valid email and mobile number you can access for months. Scan photo and signature to the exact pixel/KB limits in the notice. Name and date of birth must match educational certificates and Aadhaar where required."],bullets:["One-time registration (OTR) details saved securely","Category certificate ready if claiming reservation","Fee payment method that works on exam portals"]},{heading:"After submitting",paragraphs:["Download the application printout. Watch for correction windows — many boards allow limited field edits for a short period. Admit cards release later on the same portal; do not trust random Telegram forwards."]}]},{slug:"chatgpt-how-to-use-for-students-india",section:"ai-tools",title:"ChatGPT — How to Use It for Studies in India (Practical Guide)",shortTitle:"ChatGPT for students",description:"A simple India-focused guide to using ChatGPT for explanations, practice questions, and writing help — plus privacy and academic honesty tips.",keywords:["chatgpt how to use india","ai for students india"],readingMinutes:5,updatedLabel:"Jul 2026",relatedHref:"/tools",relatedLabel:"Free India tools",blocks:[{heading:"Good uses",paragraphs:["Ask for step-by-step explanations of a concept, alternative examples, or a quiz on a chapter you already studied. Paste your own notes and request a shorter revision sheet. For language practice, ask it to correct grammar and explain why."]},{heading:"Limits & honesty",paragraphs:["Models can invent facts, especially dates and citations. Cross-check exam-critical information with textbooks and official syllabi. Do not submit AI text as your own assignment if your school or university forbids it — use AI as a tutor, not a ghostwriter."],bullets:["Never paste passwords, OTPs, or full ID documents into chat tools","Prefer official apps/sites; avoid cracked “premium” APKs","For maths, verify every step yourself"]}]},{slug:"free-ai-tools-starter-pack-india",section:"ai-tools",title:"Free AI Tools Starter Pack for Creators in India",shortTitle:"Free AI starter pack",description:"A practical starter set of free AI tools for writing, images, and productivity — with safety notes for Indian creators.",keywords:["free ai tools india","ai tools for creators"],readingMinutes:5,updatedLabel:"Jul 2026",relatedHref:"/tools",relatedLabel:"ContentVerse India tools",blocks:[{heading:"Pick tools by job-to-be-done",paragraphs:["Use one chat model for drafting, one image tool for thumbnails, and a transcript/summary tool for long videos. Switching between ten apps usually wastes time. Start with free tiers, export your work, and keep an offline copy."]},{heading:"Pair AI with ContentVerse India utilities",paragraphs:["After drafting, use ContentVerse India Tools for calculators, PDF merge/split, and salary tax estimates — tasks that need deterministic answers, not generative guesses."]}]},{slug:"where-to-watch-ott-india",section:"movies",title:"Where to Watch Movies & Web Series in India (OTT Guide)",shortTitle:"Where to watch OTT",description:"Find legal OTT options in India — how to check release windows, platform exclusives, and why piracy links are risky.",keywords:["where to watch ott india","netflix prime jiocinema guide"],readingMinutes:5,updatedLabel:"Jul 2026",relatedHref:"/cineverse",relatedLabel:"Open CineVerse",blocks:[{heading:"Release windows differ by title",paragraphs:["Theatrical films may hit OTT weeks or months later. Some shows are exclusive to one platform in India even if they air elsewhere globally. Always check the platform’s India catalogue or an official press note — third-party “watch free” sites are often malware or piracy."]},{heading:"Use CineVerse to track interest",paragraphs:["Browse and save titles on CineVerse, then confirm the legal streaming home on the official OTT app. For cricket documentaries or sports films, Sports coverage and CineVerse can complement each other without duplicate thin pages."]}]},{slug:"movie-release-cast-watch-checklist",section:"movies",title:"Movie / Web Series Checklist — Release Date, Cast & Where to Watch",shortTitle:"Release & cast checklist",description:"A reusable checklist for any India movie or web series page: release date, cast, certification, and legal watch options.",keywords:["movie release date cast where to watch","web series india checklist"],readingMinutes:4,updatedLabel:"Jul 2026",relatedHref:"/cineverse",relatedLabel:"Browse movies",blocks:[{heading:"Minimum useful facts",paragraphs:["Readers searching “[Title] cast” or “[Title] OTT” want structured answers. Cover: official release date (India), primary cast, director, language, age rating if announced, and confirmed streaming or theatrical status."],bullets:["Release date (India) + format (theatre / OTT / both)","Main cast (3–6 names) + creator/director","Where to watch legally (or “theatrical only for now”)","One-line spoiler-free premise"]},{heading:"Template we use on ContentVerse India",paragraphs:["Our Movies / OTT guides follow “[Title] — Release Date, Cast & Where to Watch”. That matches how people search and keeps pages useful even after the premiere week."]}]}];function g(a){return e.find(b=>b.slug===a)}function h(a){return f.filter(b=>b.section===a)}function i(a,b){return f.find(c=>c.section===a&&c.slug===b)}function j(a){return`${d}/${a}`}function k(a){return`${d}/${a.section}/${a.slug}`}function l(){return[{path:d,changeFrequency:"daily",priority:.9},...e.map(a=>({path:j(a.slug),changeFrequency:"weekly",priority:.86})),...f.map(a=>({path:k(a),changeFrequency:"monthly",priority:.8}))]}}};